import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Final round: no future retaliation, so defect.
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    op_c = 0
    op_d = 0
    for a in op:
        if a == 'C':
            op_c += 1
        else:
            op_d += 1
    my_c = 0
    my_d = 0
    for a in me:
        if a == 'C':
            my_c += 1
        else:
            my_d += 1

    last_me = me[-1]
    last_op = op[-1]

    # Recent opponent cooperation over last 10
    start = n - 10
    if start < 0:
        start = 0
    rec_op_c = 0
    for i in range(start, n):
        if op[i] == 'C':
            rec_op_c += 1
    rec_len = n - start
    rec_op_d = rec_len - rec_op_c

    # Pure cooperator detection: exploit systematically, especially late.
    if op_d == 0:
        if n < 3:
            return 'C'
        # Alternate short exploit/cooperate to keep them cooperating.
        if n >= 90:
            return 'D'
        if n >= 60:
            return 'D' if rng.random() < 0.55 else 'C'
        return 'D' if rng.random() < 0.18 else 'C'

    # Pure defector: defect too, occasionally test.
    if op_c == 0:
        if n >= 4 and n % 7 == 0:
            return 'C'
        return 'D'

    # Very cooperative opponent: cooperate, retaliate once if provoked,
    # with light late exploitation.
    if op_d <= max(1, n // 12):
        if last_op == 'D':
            return 'D'
        if n >= 92:
            return 'D' if rng.random() < 0.5 else 'C'
        if n >= 70 and last_me == 'D':
            return 'C'
        return 'C'

    # Very defective opponent: punish, but probe periodically.
    if op_c <= n // 4:
        if last_op == 'C' and rng.random() < 0.7:
            return 'C'
        if last_me == 'D' and last_op == 'D':
            # try to break the DD trap
            if rng.random() < 0.35:
                return 'C'
        if n % 9 == 0:
            return 'C'
        return 'D'

    # Recent heavy defection from opponent: punish firmly.
    if rec_op_d >= 5:
        if last_op == 'C' and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Mutual defection spiral: escalate cooperation attempt.
    if last_me == 'D' and last_op == 'D':
        if rng.random() < 0.55:
            return 'C'
        return 'D'

    # Opponent defected last: retaliate, with forgiveness keyed to their rate.
    if last_op == 'D':
        # forgive more if they are otherwise cooperative
        if op_c * 2 >= n and rng.random() < 0.3:
            return 'C'
        if rec_op_c >= 6 and rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    # If we've been exploiting a cooperative opponent, ease back.
    if my_d > op_d + 2 and rng.random() < 0.6:
        return 'C'
    # Light probing in midgame to keep opponents honest.
    if 10 < n < 80 and rng.random() < 0.035:
        return 'D'
    return 'C'
